{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META AS WITH SKU_META_MASTER AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, COALESCE( MAX( CASE WHEN CATEGORY IS NOT NULL AND TRIM(CATEGORY) <> \'\' THEN CASE WHEN UPPER(TRIM(CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'TSHIRT\', \'T SHIRT\', \'T-SHIRT\', \'T-SHIRTS\', \'POLO\', \'POLOS\') THEN \'T-SHIRTS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'OVERSHIRTS\', \'OVER SHIRT\', \'OVERSHIRT\') THEN \'OVERSHIRT\' WHEN UPPER(TRIM(CATEGORY)) IN (\'SWEAT SHIRT\', \'SWEAT SHIRTS\', \'SWEATSHIRT\', \'SWEATSHIRTS\') THEN \'SWEATSHIRTS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'TRACKPANTS\', \'TRACK PANTS\', \'JOGGER\', \'JOGGERS\', \'JOGGERS & TRACKPANTS\') THEN \'JOGGERS AND TRACKPANTS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'CARGO\', \'CARGOS\', \'CARGO PANTS\') THEN \'CARGO PANTS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'COORD\', \'COORDS\', \'CO-ORD\', \'CO-ORDS\') THEN \'COORDS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'BOXER\', \'BOXERS\') THEN \'BOXERS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'BAG\', \'BAGS\', \'BACKPACK\', \'BACKPACKS\') THEN \'BAGS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'PERFUME\', \'PERFUMES\', \'FRAGRANCE\') THEN \'PERFUMES\' WHEN UPPER(TRIM(CATEGORY)) IN (\'SUNGLASS\', \'SUNGLASSES\', \'GOGGLES\') THEN \'SUNGLASSES\' WHEN UPPER(TRIM(CATEGORY)) IN (\'BELT\', \'BELTS\') THEN \'BELTS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'SHOE\', \'SHOES\', \'SNEAKER\', \'SNEAKERS\', \'FOOTWEAR\') THEN \'SHOES\' WHEN UPPER(TRIM(CATEGORY)) IN (\'SOCK\', \'SOCKS\', \'ACCESSORY\', \'ACCESSORIES\', \'CAP\', \'CAPS\') THEN \'ACCESSORIES\' ELSE UPPER(TRIM(CATEGORY)) END ELSE NULL END ), MAX( CASE WHEN LOWER(LEFT(SKU_GROUP, 5)) = \'4msfr\' THEN \'PERFUMES\' WHEN LOWER(LEFT(SKU_GROUP, 5)) IN (\'4lshs\', \'4bshs\', \'4lsfs\', \'4bsfs\') THEN \'SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 5)) IN (\'4lswt\', \'4bswt\') THEN \'SWEATSHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4mss\', \'4msn\', \'4shs\', \'4sfs\') THEN \'SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4mst\', \'4lrn\', \'4brn\', \'4lpl\', \'4bpl\') THEN \'T-SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4msr\', \'4ltr\', \'4btr\', \'4lch\', \'4bch\', \'4mtr\') THEN \'TROUSERS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4msh\', \'4lsh\', \'4bsh\') THEN \'SHORTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4mvk\', \'4msd\', \'4lje\', \'4bje\') THEN \'JEANS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4mtp\', \'4ljo\', \'4bjo\') THEN \'JOGGERS AND TRACKPANTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4msw\', \'4lsw\', \'4bsw\') THEN \'SWEATERS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lhd\', \'4bhd\') THEN \'HOODIES\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4ljk\', \'4bjk\') THEN \'JACKETS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4los\', \'4bos\') THEN \'OVERSHIRT\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lbl\', \'4bbl\') THEN \'BLAZERS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lca\', \'4bca\') THEN \'CARGO PANTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lcd\', \'4bcd\') THEN \'COORDS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4sho\' THEN \'SHOES\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4tru\' THEN \'INNERWEAR\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4mcp\', \'4mbd\') THEN \'ACCESSORIES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) IN (\'4rn\', \'4pl\') THEN \'T-SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) IN (\'4tr\', \'4ch\') THEN \'TROUSERS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4je\' THEN \'JEANS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4jk\' THEN \'JACKETS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4sw\' THEN \'SWEATERS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4hd\' THEN \'HOODIES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4os\' THEN \'OVERSHIRT\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4sh\' THEN \'SHORTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4bl\' THEN \'BLAZERS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4ca\' THEN \'CARGO PANTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4cd\' THEN \'COORDS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4jo\' THEN \'JOGGERS AND TRACKPANTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4bx\' THEN \'BOXERS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4bg\' THEN \'BAGS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4br\' THEN \'INNERWEAR\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4ac\' THEN \'ACCESSORIES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4su\' THEN \'SUNGLASSES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4bt\' THEN \'BELTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4pr\' THEN \'PERFUMES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4py\' THEN \'PYJAMAS\' WHEN LOWER(LEFT(SKU_GROUP, 2)) = \'bp\' THEN \'BAGS\' WHEN LOWER(LEFT(SKU_GROUP, 2)) = \'sh\' THEN \'SHOES\' WHEN LOWER(LEFT(SKU_GROUP, 2)) = \'sn\' THEN \'SUNGLASSES\' ELSE \'UNKNOWN\' END ), \'UNKNOWN\' ) AS CATEGORY, COALESCE(MAX( CASE WHEN UPPER(STYLE) LIKE \'%LUXE%\' OR UPPER(SKU_GROUP) LIKE \'4MLX%\' OR UPPER(SKU_GROUP) LIKE \'4LRN%\' THEN \'LUXE\' WHEN UPPER(STYLE) LIKE \'%PLUS%\' OR UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' THEN \'PLUS\' ELSE \'SNITCH\' END ), \'SNITCH\') AS STYLE, COALESCE(MAX( CASE WHEN UPPER(CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN TRIM(LOWER(COLLAR_NEW)) IN (\'polo\',\'cuban\',\'baseball\',\'mandarin\',\'mock\',\'high neck\',\'zip\',\'spread\') THEN \'POLO\' ELSE \'ROUND\' END WHEN UPPER(CATEGORY) = \'SHIRTS\' THEN CASE WHEN LOWER(STYLE) LIKE \'%linen%\' OR UPPER(MATERIAL_NEW) = \'LINEN\' THEN \'LINEN\' WHEN UPPER(MATERIAL_NEW) = \'COTTON\' THEN \'COTTON\' ELSE \'POLYESTER\' END WHEN UPPER(CATEGORY) IN (\'TROUSERS\', \'CHINOS\') THEN CASE WHEN UPPER(FIT) IN (\'SLIM FIT\') THEN \'SLIM FIT\' ELSE \'STRAIGHT FIT\' END WHEN UPPER(CATEGORY) = \'JEANS\' THEN CASE WHEN UPPER(FIT) = \'SLIM FIT\' THEN \'SLIM FIT\' WHEN UPPER(FIT) = \'SKINNY FIT\' THEN \'SKINNY FIT\' ELSE \'STRAIGHT FIT\' END END ), \'NA\') AS META1, COALESCE(MAX( CASE WHEN UPPER(CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(STYLE)) LIKE \'%TECHNICAL%\' THEN \'TECHNICAL\' WHEN UPPER(TRIM(DESIGNS)) = \'SOLID\' THEN \'CORE\' ELSE \'FASHION\' END WHEN UPPER(CATEGORY) = \'SHIRTS\' THEN CASE WHEN UPPER(TRIM(DESIGNS)) = \'SOLID\' THEN \'SOLID\' WHEN UPPER(TRIM(DESIGNS)) = \'STRIPES\' THEN \'STRIPES\' ELSE \'PRINTED\' END END ), \'NA\') AS META2, COALESCE(MAX( CASE WHEN UPPER(CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(FIT)) IN (\'OVERSIZED\',\'BOX FIT\',\'RELAXED FIT\') THEN \'OVERSIZED FIT\' WHEN UPPER(TRIM(FIT)) = \'SLIM FIT\' THEN \'SLIM FIT\' ELSE \'REGULAR FIT\' END END ), \'NA\') AS META3 FROM SNITCH_DB.MAPLEMONK.METAFIELDS_DATA GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), SKU_MRP AS ( SELECT CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END AS SKU_GROUP, REGEXP_REPLACE(UPPER(TRIM( CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END )), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, MAX(TRY_CAST(MRP AS NUMBER(10,2))) AS MRP FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE MRP IS NOT NULL AND TRIM(MRP) != \'\' AND TRY_CAST(MRP AS NUMBER(10,2)) > 0 GROUP BY 1, 2 ), CLEAN_AVAILABILITY AS ( SELECT M.CATEGORY, M.STYLE, M.META1, M.META2, M.META3, U.MRP AS PRICE FROM SKU_MRP U INNER JOIN SKU_META_MASTER M ON U.CLEAN_SKU_GROUP = M.CLEAN_SKU_GROUP WHERE M.CATEGORY IS NOT NULL AND M.CATEGORY <> \'UNKNOWN\' AND TRIM(M.CATEGORY) <> \'\' ), CAT_BOUNDS AS ( SELECT CATEGORY, STYLE, META1, META2, META3, FLOOR(MIN(PRICE) / 200) * 200 AS START_PRICE, CEIL(MAX(PRICE) / 200) * 200 AS END_PRICE FROM CLEAN_AVAILABILITY GROUP BY CATEGORY, STYLE, META1, META2, META3 ), SLAB_GENERATOR AS ( SELECT C.CATEGORY, C.STYLE, C.META1, C.META2, C.META3, SEQ.SEQ + 1 AS SLAB_NUMBER, CONCAT(\'SLAB_\', SEQ.SEQ + 1) AS PRICE_SLAB_CODE, (C.START_PRICE + (SEQ.SEQ * 200)) AS SLAB_MIN_PRICE, (C.START_PRICE + (SEQ.SEQ * 200) + 199) AS SLAB_MAX_PRICE FROM CAT_BOUNDS C JOIN ( SELECT ROW_NUMBER() OVER (ORDER BY NULL) - 1 AS SEQ FROM TABLE(GENERATOR(ROWCOUNT => 100)) ) SEQ ON (C.START_PRICE + (SEQ.SEQ * 200)) < C.END_PRICE ) SELECT CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, SLAB_MIN_PRICE, SLAB_MAX_PRICE, CONCAT(\'₹\', SLAB_MIN_PRICE, \' – ₹\', SLAB_MAX_PRICE) AS PRICE_RANGE_LABEL, CURRENT_TIMESTAMP() AS UPDATED_AT FROM SLAB_GENERATOR ORDER BY CATEGORY, STYLE, META1, META2, META3, SLAB_MIN_PRICE;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            